long long countDivisible(const vector<long long>& a, int k) {
    vector<long long> cnt(k, 0);
    cnt[0] = 1;                       // pusty prefiks
    long long s = 0;
    for (long long x : a) {
        s = ((s + x) % k + k) % k;    // reszta zawsze w [0, k)
        cnt[s]++;
    }
    long long result = 0;
    for (long long c : cnt) result += c * (c - 1) / 2;
    return result;
}

