#include <bits/stdc++.h>
using namespace std;

struct SparseTable {
    vector<vector<int>> st;   // st[k][i] = min(a[i .. i + 2^k - 1])

    SparseTable(const vector<int>& a) {
        int n = a.size();
        int levels = __lg(max(n, 1)) + 1;
        st.assign(levels, vector<int>(n));
        st[0] = a;
        for (int k = 1; k < levels; k++)
            for (int i = 0; i + (1 << k) <= n; i++)
                st[k][i] = min(st[k - 1][i], st[k - 1][i + (1 << (k - 1))]);
    }

    int query(int l, int r) const {   // min na [l, r], 0-indeksowane, l <= r
        int k = __lg(r - l + 1);
        return min(st[k][l], st[k][r - (1 << k) + 1]);
    }
};

int main() {
