    cin.tie(nullptr);
    int n, q;
    cin >> n >> q;
    vector<int> a(n);
    for (int& x : a) cin >> x;
    SparseTable st(a);
    while (q--) {
        int l, r;               // 1-indeksowane w wejściu
        cin >> l >> r;
        cout << st.query(l - 1, r - 1) << '\n';
    }
}

