// suma na [l, r] w O(log n) przez rozłączne bloki (dla porównania; w praktyce użyj sum prefiksowych)
long long sumQuery(const vector<vector<long long>>& st, int l, int r) {
    long long s = 0;
    for (int k = (int)st.size() - 1; k >= 0; k--)
        if (l + (1 << k) - 1 <= r) {
            s += st[k][l];
            l += 1 << k;
        }
    return s;
}

struct GcdTable {
    vector<vector<long long>> st;
    GcdTable(const vector<long long>& a) {
        int n = a.size(), levels = __lg(max(n, 1)) + 1;
        st.assign(levels, vector<long long>(n));
        st[0] = a;
        for (int k = 1; k < levels; k++)
            for (int i = 0; i + (1 << k) <= n; i++)
                st[k][i] = gcd(st[k - 1][i], st[k - 1][i + (1 << (k - 1))]);
    }
