        int k = __lg(r - l + 1);
        return gcd(st[k][l], st[k][r - (1 << k) + 1]);
    }
};

struct ArgMinTable {
    vector<int> a;
    vector<vector<int>> st;   // indeksy
    int better(int i, int j) const { return (a[j] < a[i] || (a[j] == a[i] && j < i)) ? j : i; }
    ArgMinTable(const vector<int>& v) : a(v) {
        int n = a.size(), levels = __lg(max(n, 1)) + 1;
        st.assign(levels, vector<int>(n));
        for (int i = 0; i < n; i++) st[0][i] = i;
        for (int k = 1; k < levels; k++)
            for (int i = 0; i + (1 << k) <= n; i++)
                st[k][i] = better(st[k - 1][i], st[k - 1][i + (1 << (k - 1))]);
    }
    int query(int l, int r) const {
        int k = __lg(r - l + 1);
        return better(st[k][l], st[k][r - (1 << k) + 1]);
    }
};

