// Ręczny kopiec minimum na tablicy: dzieci i to 2i+1 i 2i+2, rodzic to (i-1)/2.
struct MinHeap {
    vector<long long> h;

    void push(long long x) {          // O(log n): wstaw na koniec i przepychaj w górę
        h.push_back(x);
        int i = h.size() - 1;
        while (i > 0) {
            int parent = (i - 1) / 2;
            if (h[parent] <= h[i]) break;
            swap(h[parent], h[i]);
            i = parent;
        }
    }
    long long top() const { return h[0]; }
    void pop() {                      // O(log n): ostatni na miejsce korzenia i w dół
        h[0] = h.back();
        h.pop_back();
        int i = 0, n = h.size();
        while (true) {
            int l = 2 * i + 1, r = 2 * i + 2, smallest = i;
            if (l < n && h[l] < h[smallest]) smallest = l;
            if (r < n && h[r] < h[smallest]) smallest = r;
            if (smallest == i) break;
            swap(h[i], h[smallest]);
            i = smallest;
        }
    }
    bool empty() const { return h.empty(); }
    int size() const { return h.size(); }
};

