#include <bits/stdc++.h>
using namespace std;

// Bloki z sumą: zmiana wartości w punkcie O(1), suma na przedziale O(sqrt n).
struct SqrtDecomposition {
    int n, B;
    vector<long long> a, blockSum;

    SqrtDecomposition(const vector<long long>& init) : n(init.size()), a(init) {
        B = max(1, (int)sqrt(n));
        blockSum.assign(n / B + 1, 0);
        for (int i = 0; i < n; i++) blockSum[i / B] += a[i];
    }
    void assign(int i, long long v) {     // a[i] = v
        blockSum[i / B] += v - a[i];
        a[i] = v;
    }
    long long query(int l, int r) const { // suma a[l..r], 0-indeksowane
        long long s = 0;
        while (l <= r && l % B != 0) s += a[l++];               // początek niepełnego bloku
        while (l + B - 1 <= r) { s += blockSum[l / B]; l += B; } // pełne bloki
        while (l <= r) s += a[l++];                              // końcówka
        return s;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, q;
    cin >> n >> q;
    vector<long long> a(n);
    for (auto& x : a) cin >> x;
    SqrtDecomposition sd(a);
    while (q--) {
        int type;
        cin >> type;
        if (type == 1) {          // 1 i v: a[i] = v
            int i;
            long long v;
            cin >> i >> v;
            sd.assign(i - 1, v);
        } else {                  // 2 l r: suma
            int l, r;
            cin >> l >> r;
            cout << sd.query(l - 1, r - 1) << '\n';
        }
    }
}

// Dodawanie na przedziale + suma na przedziale: lazy na pełnych blokach.
struct SqrtRangeAdd {
    int n, B;
    vector<long long> a, sum, lazy;   // a[i] bez lazy swojego bloku
    SqrtRangeAdd(int n) : n(n), B(max(1, (int)sqrt(n))), a(n, 0), sum(n / B + 1, 0), lazy(n / B + 1, 0) {}
    void add(int l, int r, long long v) {
        while (l <= r && l % B != 0) { a[l] += v; sum[l / B] += v; l++; }
        while (l + B - 1 <= r) { lazy[l / B] += v; l += B; }
        while (l <= r) { a[l] += v; sum[l / B] += v; l++; }
    }
    long long query(int l, int r) const {
        long long s = 0;
        while (l <= r && l % B != 0) { s += a[l] + lazy[l / B]; l++; }
        while (l + B - 1 <= r) { s += sum[l / B] + lazy[l / B] * B; l += B; }
        while (l <= r) { s += a[l] + lazy[l / B]; l++; }
        return s;
    }
};

