vector<int> distinctOffline(const vector<int>& a, vector<array<int, 3>> qs) {   // qs: {l, r, idx}, 0-indeksowane
    int n = a.size();
    vector<int> bit(n + 1, 0), ans(qs.size());
    auto add = [&](int i, int v) { for (i++; i <= n; i += i & -i) bit[i] += v; };
    auto sum = [&](int i) { int s = 0; for (i++; i > 0; i -= i & -i) s += bit[i]; return s; };
    sort(qs.begin(), qs.end(), [](const array<int, 3>& x, const array<int, 3>& y) { return x[1] < y[1]; });
