    for (auto [l, r, idx] : qs) {
        for (; j <= r; j++) {
            auto it = last.find(a[j]);
            if (it != last.end()) add(it->second, -1);
            last[a[j]] = j;
            add(j, +1);
        }
        ans[idx] = sum(r) - (l > 0 ? sum(l - 1) : 0);
    }
    return ans;
}

